VALUES ('armenian_elementary', 3, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"true_false","answer":"Ճիշտ է","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":2,"points":0.5,"type":"fill_blank","answer":"ձայնավոր","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":3,"points":1,"type":"multiple_choice","answer":"սարյակ, թերթ, նուռ","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":4,"points":1,"type":"short_answer","answer":"Անխիղճ","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":5,"points":1,"type":"multiple_choice","answer":"Շատրվանները ցայտում են։ Տղաները ֆուտբոլ էին խաղում։","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,5 միավոր"},{"number":6,"points":1,"type":"fill_blank","answer":"ձմեռ — ամառ; հարավ — հյուսիս; գիշեր — ցերեկ; հաղթանակ — պարտություն","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,25 միավոր"},{"number":7,"points":1,"type":"short_answer","answer":"մկրատ, տնակ, արև, հայուհի (մնացածը սխալ են վանկատված)","scoring_notes":"Յուրաքանչյուր զույգ ճիշտ պատասխան՝ 0,25 միավոր"},{"number":8,"points":0.5,"type":"short_answer","answer":"Թաքնված հնչյունը ը-ն է («թըռչուն»); այդ հնչյունով բառ, օր.՝ ընձուղտ","accepted_variants":["ընձուղտ","ընկեր","ընտանիք","ընթերցել"],"scoring_notes":"Ընդունվում է ը հնչյուն պարունակող ցանկացած վավեր բառ. Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":9,"points":0.5,"type":"fill_blank","answer":"գառ → գառներ; շրջան → շրջաններ; կին → կանայք; մարդ → մարդիկ","scoring_notes":"Յուրաքանչյուր զույգի ճիշտ պատասխան՝ 0,25 միավոր"},{"number":10,"points":1,"type":"short_answer","answer":"Երեխաները սպասում էին։","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":11,"points":1,"type":"short_answer","answer":"վերարկու → վե-րար-կու, վե-րարկու, վերար-կու; պատանի → պա-տա-նի, պա-տանի, պատա-նի","scoring_notes":"Յուրաքանչյուր բառը տողադարձվում է 3 ձևով. Մեկ բառը բոլոր ձևերով ճիշտ՝ 0,5 միավոր"},{"number":12,"points":1,"type":"short_answer","answer":"տոնածառ = տոն + ա + ծառ → տոնական; հայրասեր = հայր + ա + սեր → հայրենի","scoring_notes":"Յուրաքանչյուր քայլի համար 0,25 միավոր՝ բաղադրիչների բաժանում և նոր բառի կազմում"},{"number":13,"points":1.5,"type":"fill_blank","answer":"Շատի հետևից ընկնողը, քիչն էլ կկորցնի։ Ծույլը հաց ուտելիս առողջ է, սովորելիս՝ հիվանդ։ Լավ է գիտունին գերի, քան՝ անգետին սիրելի։","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,5 միավոր"},{"number":14,"points":1.5,"type":"short_answer","answer":"ցորեն ու նուռ առա","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":15,"points":2,"type":"essay","answer":"Վերնագիր՝ «Վեճ». Մոդելային վերջաբան՝ «…մոլորակում կյանք չի կարող լինել։ Ամպը չհամաձայնվեց՝ ասելով, որ եթե ինքը չլինի, անձրև չի գա, և բոլոր բույսերն ու կենդանիները կմեռնեն։ Այսպես նրանք երկար վիճեցին, մինչև բարկությունից անձրևը սկսեց տեղալ, իսկ արևը փորձեց ավելի ուժեղ շողալ։ Այդ պահին երկնքում հայտնվեց բազմագույն ծիածանը և ասաց, որ երկուսն էլ նույնքան կարևոր են բնության գոյության համար։»","scoring_notes":"Վերնագիր՝ 0,5; հիմնավորված վերջաբան՝ 0,5; անձրևի, արևի և ծիածանի կապի բացահայտում՝ 0,5; գրագետ և կապակցված շարադրանք՝ 0,5 միավոր"}]'::jsonb, 'Header says 2026-2027. Q1 turns on the schwa: «նկար» is written with 4 letters but pronounced «նըկար», 5 sounds — hence Ճիշտ է. Q8''s hidden sound is the ը in «թռչուն». Q15 shows a picture alongside the story opening. All-or-nothing questions (full mark or zero): Q1, Q2, Q3, Q4, Q8, Q10, Q14.', '1wFIFotDeXpDYZ665vxa2llkOFIZlTLts')
