VALUES ('armenian_elementary', 4, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"fill_blank","answer":"Օ տառը","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":2,"points":0.5,"type":"multiple_choice","answer":"տաղ, երգ","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":3,"points":1,"type":"fill_blank","answer":"թագավոր — ո՞վ; երգեր — ինչե՞ր; կարաս — ի՞նչ; աղջիկներ — ովքե՞ր","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,25 միավոր"},{"number":4,"points":1,"type":"short_answer","answer":"Հեռախոսն ու համակարգիչը իմ օգնականներն են։","scoring_notes":"Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":5,"points":1,"type":"fill_blank","answer":"զննել, որևէ, տարօրինակ, վայրկյան","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,25 միավոր"},{"number":6,"points":1,"type":"fill_blank","answer":"ծանր — թեթև; կրտսեր — ավագ; վախկոտ — քաջ (արի); բարեկամ — թշնամի","accepted_variants":["վախկոտ — արի"],"scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,25 միավոր"},{"number":7,"points":1,"type":"table","answer":"Գոյական՝ երազ; Ածական՝ պայծառ; Բայ՝ մաքրել; Թվական՝ վեցերորդ","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,25 միավոր"},{"number":8,"points":0.5,"type":"diagram","answer":"Գյուղը կանգնի՝ գերան կկոտրի։","scoring_notes":"Նկարից կախված. Ամբողջական՝ ճիշտ պատասխանի դեպքում ամբողջ միավորը, այլապես 0"},{"number":9,"points":0.5,"type":"fill_blank","answer":"Սաթենիկի քրոջ անունը Գեղեցիկ է։ Անուշիկը գեղեցիկ զգեստ է հագել։","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,25 միավոր. Առաջինը հատուկ անուն է՝ մեծատառով"},{"number":10,"points":1,"type":"table","answer":"Ուղիղ իմաստ՝ մարդու բերան, մարդու գլուխ; Փոխաբերական իմաստ՝ կրակի բերան, սոխի գլուխ","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,25 միավոր. Նկարից կախված"},{"number":11,"points":1,"type":"fill_blank","answer":"հավաքել — հավաք; զանգել — զանգ; ջրել — ջուր; ներկել — ներկ","scoring_notes":"Յուրաքանչյուր ճիշտ պատասխան՝ 0,25 միավոր"},{"number":12,"points":1,"type":"short_answer","answer":"Ենթակա՝ Հովհաննես Թումանյանը (մեկ գծով); Ստորոգյալ՝ գրել է (երկու գծով)","scoring_notes":"Ենթական գտնելու և գծելու համար՝ 0,5 միավոր; ստորոգյալինը՝ 0,5 միավոր"},{"number":13,"points":1.5,"type":"short_answer","answer":"Մրջյունին և մեղվին բնութագրող ընդհանուր հատկանիշներ, օր.՝ ժրաջան, աշխատասեր, ճարպիկ, խայթող, փոքրիկ, միջատ","accepted_variants":["ժրաջան","աշխատասեր","ճարպիկ","խայթող","փոքրիկ","միջատ"],"scoring_notes":"Յուրաքանչյուր ճիշտ հատկանիշ՝ 0,5 միավոր (3 հատկանիշ)"},{"number":14,"points":1.5,"type":"short_answer","answer":"Օր.՝ Ի՞նչ են ցույց տալիս առարկա ցույց տվող բառերը (գոյական); Ի՞նչն է պատասխանում ինչպիսի՞ հարցին (ածականը); Ի՞նչն է ցույց տալիս թիվ և թվային կարգ (թվականը)","scoring_notes":"Յուրաքանչյուր հարցի ճիշտ կազմության դեպքում՝ 0,5 միավոր"},{"number":15,"points":2,"type":"essay","answer":"Հայաստան բառը ծնվել է հայերի ոստան բառից և նշանակում է հայերի երկիր; այն Հայկ Նահապետի անունից է առաջացել՝ Հայք → Հայաստան, Հայկի երկիր. Հայրենասեր բառը ծնվել է հայրենիք սիրող մարդկանց շնորհիվ, ովքեր հոգ են տանում իրենց հայրենիքի մասին — օրինակ՝ աղբ չեն թափում ու մաքուր են պահում շրջապատը","scoring_notes":"Գրագետ, կապակցված շարադրանք՝ 0,5; հիմնավորված մեկնաբանություն օրինակներով՝ 0,5; արժեքները բացահայտող մտքեր՝ 0,5; քննական և վերլուծական տարրեր՝ 0,5 միավոր"}]'::jsonb, '2025-2026 edition. Q8 and Q10 are picture-based. The Q6 key is printed in column order; the pairings are written out explicitly here so they cannot be misread. All-or-nothing questions (full mark or zero): Q1, Q2, Q4, Q8.', '1LjFxnLRZIZqb1S4lK2aEKwmcZLMXwiDt')
