VALUES ('biology', 10, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"short_answer","answer":"Բարդ ածխաջուր (բազմաշաքար)","accepted_variants":["բարդ","բազմաշաքարներ","պոլիսախարիդ"],"scoring_notes":"Նկարից կախված"},{"number":2,"points":0.5,"type":"short_answer","answer":"Պլաստիկ փոխանակություն","accepted_variants":["ասիմիլացիա"],"scoring_notes":"Նկարից կախված"},{"number":3,"points":1,"type":"multiple_choice","answer":"ա - 1. ԴՆԹ-ի կրկնապատկում; բ - 3. ինտերֆազ","scoring_notes":"2 x 0,5 միավոր. Նկարից կախված"},{"number":4,"points":1,"type":"short_answer","answer":"ա. Լուսային փուլ; բ. ԱԵՖ","accepted_variants":["թթվածին","ատոմային ջրածին"],"scoring_notes":"2 x 0,5 միավոր"},{"number":5,"points":1,"type":"matching","answer":"Էնդոպլազմային ցանց - բ; Ռիբոսոմ - ա; Լիզոսոմ - դ; Պլաստիդ - գ","scoring_notes":"4 x 0,25 միավոր"},{"number":6,"points":1,"type":"diagram","answer":"Պլազմալեմ (պլազմային թաղանթ)","accepted_variants":["պլազմային թաղանթ","պլազմալեմ","բջջաթաղանթ"],"scoring_notes":"Նկարից կախված"},{"number":7,"points":1,"type":"short_answer","answer":"Նմանություն՝ երկուսն էլ բջջի բաժանման եղանակ են, երկուսն էլ սկսվում են մեկ դիպլոիդ բջջից, երկուսին էլ նախորդում է ինտերֆազ. Տարբերություն՝ միտոզի արդյունքում ձևավորվում է երկու դիպլոիդ բջիջ, իսկ մեյոզի արդյունքում՝ չորս հապլոիդ; մեյոզը սեռական բջիջների առաջացումն է, միտոզը՝ մարմնական; մեյոզն ունի երկու բաժանում, միտոզը՝ մեկ","scoring_notes":"2 x 0,5 միավոր"},{"number":8,"points":0.5,"type":"multiple_choice","answer":"4","scoring_notes":"Նկարից կախված"},{"number":9,"points":0.5,"type":"short_answer","answer":"ՈՒԱԳԱՑՈՒ"},{"number":10,"points":1,"type":"short_answer","answer":"Ընդհանրություն՝ երկու պրոցեսներն էլ ավտոտրոֆ սննդառության օրինակներ են, երկուսի դեպքում էլ անօրգանական նյութերից սինթեզվում է օրգանական. Տարբերություն՝ մի դեպքում օգտագործվում է արևի էներգիան, մյուս դեպքում՝ քիմիական ռեակցիայի էներգիան; մի դեպքում հարկավոր է քլորոֆիլ, մյուսի դեպքում՝ ոչ","scoring_notes":"2 x 0,5 միավոր. Նկարից կախված"},{"number":11,"points":1,"type":"table","answer":"ա - շարակցական; բ - նյարդային; գ - մկանային; դ - էպիթելային","scoring_notes":"4 x 0,25 միավոր. Նկարից կախված"},{"number":12,"points":1,"type":"computation","answer":"ՌՆԹ = ԴՆԹ : 2 = 1680 : 2 = 840 նուկլեոտիդ","scoring_notes":"Աղբյուրում պատասխանը գրված է 860, սակայն լուծումը տալիս է 840 — ճիշտը 840 է"},{"number":13,"points":1.5,"type":"essay","answer":"ա. Միտոքոնդրիաներն անվանում են բջջի էներգետիկ կայաններ — այնտեղ է ընթանում բջջային շնչառությունը, գլյուկոզը քայքայվում է և արտադրվում ԱԵՖ, որն ապահովում է բջջի բոլոր կենսական պրոցեսների էներգիան; բ. Վնասվելու դեպքում բջիջը չի կարողանա արտադրել բավարար ԱԵՖ — կդանդաղեն կամ կդադարեն նյութափոխանակությունը, սպիտակուցների սինթեզը, բջջային բաժանումը և վերականգնումը, բջիջը կարող է մահանալ; գ. Մկանային բջիջները շատ էներգիա են պահանջում, ուստի կառաջանա մկանային թուլություն; ուղեղի նյարդաբջիջները նույնպես՝ ուստի հիշողության կամ մտածողության խանգարումներ; երկարատև վնասումը կարող է հանգեցնել լուրջ հիվանդությունների","scoring_notes":"3 x 0,5 միավոր"},{"number":14,"points":1.5,"type":"computation","answer":"C6H12O6 + 2H3PO4 + 2ԱԿՖ = 2C3H6O3 + 2ԱԵՖ + 2H2O. 1) 1 մոլ գլյուկոզ → 2 մոլ H2O, ուստի 26 մոլ H2O → 13 մոլ գլյուկոզ; 2) 13 մոլ գլյուկոզ → 26 մոլ ԱԵՖ; 3) 1 մոլ ԱԵՖ → 40 ԿՋ, ուստի 26 x 40 = 1040 ԿՋ","scoring_notes":"Կարող են միանգամից որոշել ԱԵՖ-ը՝ առանց գլյուկոզի քանակը որոշելու"},{"number":15,"points":2,"type":"essay","answer":"ա. Օրգանիզմները միայն անսեռ եղանակով կբազմանան, բոլորը կլինեն միակերպ, չի լինի տեսակային բազմազանություն; բ. Միջավայրի կայունություն և փոփոխությունների պակաս, երբ գենետիկ փոփոխության կարիքը նվազում է; կամ երբ հարկավոր է արագ բազմանալ, իսկ ռեսուրսներն ու ժամանակը սուղ են; գ. Բացասական՝ գենետիկ բազմազանության նվազում, ինչը նվազեցնում է հարմարվողականությունը և տեսակներն ավելի խոցելի են դարձնում շրջակա միջավայրի փոփոխությունների ու հիվանդությունների նկատմամբ; դ. Դրական՝ տեսակներն ավելի քիչ ջանք ու ռեսուրս կծախսեն, ավելի արագ կբազմանան, քանակապես կավելանան","scoring_notes":"Չափանիշներ՝ 1. ներկայացրել է սեռական բազմացման կարևորությունն ու առանձնահատկությունը; 2. համեմատական է տարել անսեռ և սեռական բազմացումները"}]'::jsonb, '2025-2026 edition. Q1, Q2, Q3, Q6, Q8, Q10, Q11 are figure-dependent. DATA ERROR IN SOURCE: Q12''s stated answer is ''860'' but its own working gives 1680:2 = 840. 840 is correct and is used here — flag for content review.', '19Exf5nQMtK0qx9yVE22Dq9kU1BJJlhTM6S56I-Xtt4g')
