INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('biology', 11, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"short_answer","answer":"Կենսածին գործոն","accepted_variants":["կենսածին","բիոտիկ"],"scoring_notes":"Նկարից կախված"},{"number":2,"points":0.5,"type":"multiple_choice","answer":"2","scoring_notes":"Նկարից կախված"},{"number":3,"points":1,"type":"table","answer":"Գենային - գ; Գենոմային - ա, դ; Քրոմոսոմային - բ","scoring_notes":"4 x 0,25 միավոր"},{"number":4,"points":1,"type":"short_answer","answer":"1. Մենդելի 2-րդ օրենք (ճեղքավորման օրենք); 2. Մենդելը","accepted_variants":["ճեղքավորման օրենք","Մենդելի երկրորդ օրենք","Գրեգոր Մենդել"],"scoring_notes":"2 x 0,5 միավոր. Նկարից կախված"},{"number":5,"points":1,"type":"true_false","answer":"1. Սխալ է; 2. Ճիշտ է; 3. Ճիշտ է; 4. Սխալ է","scoring_notes":"4 x 0,25 միավոր"},{"number":6,"points":1,"type":"short_answer","answer":"ա. Մակաբուծություն (կամ գիշատչություն); բ. Օր.՝ հաբեթասունկը ծառի մակաբույծ, որդերը մարդու մակաբույծ, գայլ և նապաստակ, արծիվ և առնետ; գ. Սիմբիոտիկ հարաբերություն (մուտուալիզմ); դ. Օր.՝ քարաքոս, ծառի և սնկի փոխհարաբերություն, տերմիտները մարդու աղիներում, ազոտֆիքսող բակտերիաները մշակաբույսերի արմատներին","scoring_notes":"4 x 0,25 միավոր"},{"number":7,"points":1,"type":"short_answer","answer":"ա. Դաունի համախտանիշ; բ. 47 քրոմոսոմ","scoring_notes":"2 x 0,5 միավոր"},{"number":8,"points":0.5,"type":"table","answer":"Գամետների քանակը՝ 4; Գամետների տեսակները՝ AB, Ab, aB, ab"},{"number":9,"points":0.5,"type":"multiple_choice","answer":"ա. բ (P, Q և S); բ. Ֆոտոսինթեզ","scoring_notes":"2 x 0,25 միավոր. Դիագրամից կախված"},{"number":10,"points":1,"type":"short_answer","answer":"ա. Բաց միջատների քանակը կնվազի, քանի որ նրանք առավել նկատելի կդառնան և կոչնչացվեն թշնամիների կողմից, իսկ մուգ միջատների քանակը կավելանա; բ. Շարժական բնական ընտրություն","scoring_notes":"2 x 0,5 միավոր"},{"number":11,"points":1,"type":"short_answer","answer":"ա. Սոյան ազոտֆիքսող մշակաբույս է; բ. Ազոտֆիքսող այլ մշակաբույսեր՝ ոլոռ, երեքնուկ, լոբի; գ. Որոշ մշակաբույսերի արմատներն ունեն հանգույցներ, որոնց վրա ապրում են ազոտֆիքսող բակտերիաներ — դրանք բույսին մատակարարում են ազոտ, որն էլ փոխանցվում է հողին, իսկ բակտերիան բույսից ստանում է սնունդ","scoring_notes":"ա. 0,25; բ. 0,25; գ. 0,5 միավոր. Նկարից կախված"},{"number":12,"points":1,"type":"short_answer","answer":"ա. Նպատակը տերևների ֆոնին թշնամու կողմից աննկատ մնալն է; բ. Կիրառվում է հարմարվողականության երևույթը, մասնավորապես՝ հովանավորող գունավորումը","scoring_notes":"2 x 0,5 միավոր"},{"number":13,"points":1.5,"type":"computation","answer":"ա. Թիթեռից գորտին՝ 4 x 100/10 = 40 կգ; սկզբնական կենսազանգված՝ 40 x 100/10 = 400 կգ; բ. Օձում՝ 4 x 10/100 = 0,4 կգ, գումարային՝ 40 + 4 + 0,4 = 44,4 կգ; գ. Կորուստը թիթեռ-գորտ օղակում՝ 40 - 4 = 36 կգ","scoring_notes":"3 x 0,5 միավոր. Նկարից կախված"},{"number":14,"points":1.5,"type":"computation","answer":"A - պեպեններ, a - պեպենների բացակայություն. P ♀ aa x ♂ Aa; գամետներ՝ ♀ a, ♂ A և a; F: Aa - 50%, aa - 50%. Պատասխան՝ երեխաների կեսը կլինեն պեպենոտ, մյուս կեսը՝ առանց պեպենների","scoring_notes":"Առկա է լուծումը, ներառյալ խաչասերման սխեման"},{"number":15,"points":2,"type":"essay","answer":"Օրինակ՝ ընտրված որակը ճկունությունն է — ցանկացած իրավիճակում ճիշտ կողմնորոշվելու և արդյունավետ գործելու համար հարկավոր է մտքի ճկունություն. Գոյության կռիվն էվոլյուցիայի այն շարժիչ ուժն է, որի միջոցով բնական ընտրության արդյունքում գոյատևում են միջավայրի պայմաններին առավելագույնս հարմարվածները, իսկ ներկայիս գործատուները կարևորում են արագ կողմնորոշվելու կարողությունը","scoring_notes":"ա. 0,5; բ. 0,5; գ. 1 միավոր. Չափանիշներ՝ 1. նշել է պահանջվող 2 որակ; 2. հիմնավորել է ընտրությունը՝ հաշվի առնելով ժամանակակից աշխատաշուկայի պահանջները; 3. մեկնաբանել է գոյության կռվի տեսանկյունից"}]'::jsonb, '2025-2026 edition. Q1, Q2, Q4, Q9, Q11, Q13 are figure-dependent. Built on grade-9 topics because grade-11 content follows directly from them (stated in the source).', '1YrJ8pJWN1l3M-ZWLIVYQT-h9jDXcVJZx')
