INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('biology', 7, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"short_answer","answer":"ա. Սիրտ-անոթային (արյունատար) համակարգ; բ. Մատակարարում է արյուն","accepted_variants":["տեղափոխում է թթվածին","տեղափոխում է սննդանյութեր","արյան շրջանառություն է ապահովում"],"scoring_notes":"2 x 0,25 միավոր. Նկարից կախված"},{"number":2,"points":0.5,"type":"short_answer","answer":"Կողագիծ. Մյուս հասկացությունները բնորոշում են թռչուններին, իսկ կողագիծը՝ ձկներին","scoring_notes":"2 x 0,25 միավոր՝ ընտրություն + մեկնաբանություն"},{"number":3,"points":1,"type":"short_answer","answer":"ա. Ֆոտոսինթեզ; բ. Ապահովում է բույսերի սննդառությունը, մատակարարում է օրգանական նյութեր","scoring_notes":"2 x 0,5 միավոր. Նկարից կախված"},{"number":4,"points":1,"type":"fill_blank","answer":"Հետերոտրոֆ է","accepted_variants":["հետերոտրոֆ","հետերոտրոֆ օրգանիզմ է"]},{"number":5,"points":1,"type":"matching","answer":"Տերև → բ; Արմատ → գ; Պտուղ → դ; Ծաղիկ → ա","scoring_notes":"4 x 0,25 միավոր"},{"number":6,"points":1,"type":"table","answer":"Մարսողական → Կերակրափող; Շնչառական → Թոքեր; Արյունատար → Սիրտ; Արտազատական → Երիկամ","scoring_notes":"4 x 0,25 միավոր"},{"number":7,"points":1,"type":"diagram","answer":"ա. 5; բ. Օրգանիզմի մոտ շարժումները կդառնան անհավասարակշիռ, անկանոն","scoring_notes":"2 x 0,5 միավոր. Նկարից կախված"},{"number":8,"points":0.5,"type":"short_answer","answer":"Նմանություն՝ երկուսն էլ կենդանի օրգանիզմ են և ունեն կենդանուն բնորոշ հատկությունները (շնչում, սնվում, աճում, բազմանում են). Տարբերություն՝ ջրայիններն ունեն լողակներ, կարող են ունենալ խռիկներ, բազմացումը կատարվում է ջրային միջավայրում","scoring_notes":"2 x 0,25 միավոր՝ 1 նմանություն + 1 տարբերություն"},{"number":9,"points":0.5,"type":"short_answer","answer":"Նմանություն՝ երկուսն էլ ներքին օրգաններ են, գտնվում են կրծքավանդակի խոռոչում, կազմված են բջիջներից և հյուսվածքներից, պարունակում են արյունատար անոթներ. Տարբերություն՝ սիրտը արյունատար համակարգի օրգան է, թոքը՝ շնչառական; սրտի գործառույթն արյան մատակարարումն է, թոքինը՝ գազափոխանակությունը; սիրտը կենտ օրգան է, թոքը՝ զույգ","scoring_notes":"2 x 0,25 միավոր. Նկարից կախված"},{"number":10,"points":1,"type":"computation","answer":"1. Կծլի 80 սերմ; 2. 15 օրում 20°C-ում ծլում է սերմերի մոտ 80%-ը, իսկ 10°C-ում՝ մոտ 50%-ը, հետևաբար ծլման լավագույն ջերմաստիճանը 20°C է","scoring_notes":"2 x 0,5 միավոր. Տրամագրից կախված"},{"number":11,"points":1,"type":"diagram","answer":"Օրգան 8՝ Պսակաթերթ — սովորաբար ունի վառ գունավորում և գրավում է միջատներին; Օրգան 10՝ Բաժակաթերթ — ծաղկի արտաքին մասն է, պաշտպանում է ծաղիկը զարգացման ընթացքում","scoring_notes":"2 x 0,5 միավոր. Նկարից կախված"},{"number":12,"points":1,"type":"essay","answer":"ա. Օրգանիզմի կենսագործունեության համար հարկավոր է էներգիա; էներգիայի աղբյուրը սնունդն է, որը ճեղքվում է մարսողական համակարգում; ճեղքման համար հարկավոր է թթվածին, որը ստացվում է շնչառությամբ; ստացված էներգիան և նյութերը բոլոր օրգաններին հասցնում է արյունատար համակարգը. բ. Համագործակցության խախտումը հանգեցնում է օրգանիզմի անարդյունավետ գործունեության, հիվանդությունների, ընդհուպ մահվան","scoring_notes":"2 x 0,5 միավոր. Չափանիշ՝ ներկայացրել է երեք համակարգերի գործառույթները և նշել դրանց միջև կապը"},{"number":13,"points":1.5,"type":"short_answer","answer":"Սողունին (մողեսին), քանի որ նա սառնարյուն կենդանի է և նրա կենսագործունեությունն ու ակտիվությունը կախված են շրջակա միջավայրի ջերմաստիճանից","accepted_variants":["մողեսին","սողունին"]},{"number":14,"points":1.5,"type":"diagram","answer":"ա. Բույսի կենսական ցիկլ; բ. Նոր բույս չի առաջանա; գ. Նշված փուլը սերմերի առաջացումն է — նոր բույսերն առաջանում են սերմերից, ուստի այդ փուլի բացակայությունը հանգեցնում է բույսի չբազմանալուն","scoring_notes":"3 x 0,5 միավոր. Նկարից կախված"},{"number":15,"points":2,"type":"essay","answer":"Պատասխանում պետք է երևա երևակայական կենդանու նկարն ու անունը. Օրգաններն ու հարմարանքները պետք է համապատասխանեն ջրային միջավայրին (օր.՝ խռիկներ, լողակներ, թեփուկներ). Հիմնավորման մեջ պետք է երևա կապը կենսամիջավայրի և օրգան-համակարգերի միջև","scoring_notes":"Նկարել և անվանել՝ 0,5 միավոր; ջրային միջավայրին համապատասխան օրգաններ՝ 0,5 միավոր; հիմնավորում՝ 1 միավոր"}]'::jsonb, '2025-2026 edition. Q1, Q3, Q7, Q9, Q10, Q11, Q14 are figure-dependent. Source gives explicit acceptable-answer variants for Q1, Q8, Q9, Q12, Q15 — captured as accepted_variants seed knowledge.', '1bMfb4f-GY4uZ2_8Y5wceI1miqynJRjR3')
