INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('biology', 8, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"multiple_choice","answer":"գ","scoring_notes":"Նկարից կախված"},{"number":2,"points":0.5,"type":"multiple_choice","answer":"դ. ձախ փորոք"},{"number":3,"points":1,"type":"diagram","answer":"Ազդրոսկր","accepted_variants":["ազդր","ազդրոսկր"],"scoring_notes":"Նկարից կախված"},{"number":4,"points":1,"type":"short_answer","answer":"ա. Նեյրոն; բ. Նյարդային համակարգ","scoring_notes":"2 x 0,5 միավոր. Նկարից կախված"},{"number":5,"points":1,"type":"diagram","answer":"1 - ձախ փորոք; 2 - աջ փորոք; 3 - աջ նախասիրտ; 4 - ձախ նախասիրտ","scoring_notes":"4 x 0,25 միավոր. Նկարից կախված"},{"number":6,"points":1,"type":"fill_blank","answer":"1. ծալում; 2. պարզում","scoring_notes":"2 x 0,5 միավոր"},{"number":7,"points":1,"type":"short_answer","answer":"ա. Խռիկ; բ. Իրականացնում է շնչառություն","scoring_notes":"2 x 0,5 միավոր. Նկարից կախված"},{"number":8,"points":0.5,"type":"true_false","answer":"1. Սխալ է — դա գրգռականության օրինակ է, ինֆուզորիաները նյարդային համակարգ չունեն; 2. Ճիշտ է","scoring_notes":"2 x 0,25 միավոր"},{"number":9,"points":0.5,"type":"diagram","answer":"ա. 8; բ. 7","scoring_notes":"2 x 0,25 միավոր. Նկարից կախված"},{"number":10,"points":1,"type":"matching","answer":"1→գ, 2→ա, 3→բ, 4→դ","scoring_notes":"4 x 0,25 միավոր. Նկարից կախված"},{"number":11,"points":1,"type":"short_answer","answer":"ա. Ոչ; բ. Այդ փորձերը գրեթե երբեք հաջող չէին լինում, որովհետև կենդանիների արյունը տարբերվում է մարդու արյունից. մարդու օրգանիզմը չէր ընդունում կենդանու արյունը և դա վտանգավոր էր նրա կյանքի համար","scoring_notes":"2 x 0,5 միավոր"},{"number":12,"points":1,"type":"short_answer","answer":"ա. Արտաքին կմախք (էկզոկմախք); բ. Խխունջի կմախքը կազմված է կալցիում պարունակող միացություններից, իսկ խեցգետնինը՝ խիտինից; գ. Արտաքին կմախքը կարող է ծանր լինել, ինչը դժվարեցնում է շարժումը — այդ պատճառով այդպիսի կենդանիների մեծ մասը դանդաղաշարժ է","accepted_variants":["բ. Խխունջի կմախքն իր աճի հետ մեծանում է, իսկ խեցգետնինը՝ ոչ, և նա կատարում է մաշկափոխություն","գ. Արտաքին կմախքը կարող է օրգանիզմի աճին զուգահեռ չաճել, որի պատճառով բնորոշ է մաշկափոխությունը"],"scoring_notes":"ա. 0,25; բ. 0,25; գ. 0,5 միավոր. Նկարից կախված"},{"number":13,"points":1.5,"type":"essay","answer":"Թոքերում տեղի է ունենում գազափոխանակություն մազանոթների արյան և ներշնչած օդի միջև. ստացած թթվածինն արյունը մատակարարում է օրգաններին, իսկ այնտեղից հավաքում է ածխաթթու գազը և տեղափոխում թոքեր. այս ամբողջ գործընթացը կարգավորում է նյարդային համակարգը՝ արագացնելով կամ դանդաղեցնելով շնչառական շարժումները, արյան հոսքը, սրտի կծկումները","scoring_notes":"Չափանիշ՝ նշել է, որ գազափոխանակություն է տեղի ունենում օդի և արյան միջև; նշել է, որ կարգավորումը վերահսկվում է նյարդային համակարգի կողմից"},{"number":14,"points":1.5,"type":"computation","answer":"ա. 450 x 1440 = 648 000 կծկում/օր; բ. 250 x 1440 = 360 000 կծկում/օր; գ. 648 000 : 360 000 = 1,8 — թռչունի սիրտն ավելի շատ է աշխատում՝ 1,8 անգամ","scoring_notes":"3 x 0,5 միավոր"},{"number":15,"points":2,"type":"essay","answer":"ա. Ամենայն հավանականությամբ վնասվել է ձիու գլխուղեղը (դիմային բաժինները), ինչպես նաև գլխի մաշկն ու արյունատար անոթները — կա արտաքին արյունահոսություն, շարժումների անհավասարակշռություն և դեմքի մկանների աշխատանքի խախտում; բ. Արագ կանգնեցնել արյունահոսությունը, պահել կենդանուն հանգիստ վիճակում, կանչել անասնաբույժ կամ տեղափոխել անասնաբուժական կենտրոն; գ. Առաջնահերթ՝ կանգնեցնել արյունահոսությունը, ապահովել որ կենդանին կտրուկ չշարժվի, հետևել շնչառությանն ու սրտի աշխատանքին, շտապ տեղեկացնել անասնաբույժին","scoring_notes":"ա. 0,5; բ. 0,5; գ. 1 միավոր"}]'::jsonb, '2025-2026 edition. Q1, Q3, Q4, Q5, Q7, Q9, Q10, Q12 are figure-dependent. Source supplies explicit alternative answers for Q3 and Q12 — captured as accepted_variants.', '1ykwTZr29sjKSVKyk2yenwbcKqW-X9ymD')
