INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('biology', 9, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"multiple_choice","answer":"3","scoring_notes":"Նկարից կախված"},{"number":2,"points":0.5,"type":"multiple_choice","answer":"դ. ջուր"},{"number":3,"points":1,"type":"matching","answer":"1 - հողային; 2 - օդային; 3 - ջրային; 4 - ցամաքային","scoring_notes":"4 x 0,25 միավոր. Նկարից կախված"},{"number":4,"points":1,"type":"short_answer","answer":"ա. Սեռական բազմացում; բ. Սեռական բջիջներ","accepted_variants":["գամետներ","սպերմատոզոիդ և ձվաբջիջ"],"scoring_notes":"2 x 0,5 միավոր. Գծապատկերից կախված"},{"number":5,"points":1,"type":"true_false","answer":"ա. սխալ է; բ. ճիշտ է; գ. ճիշտ է; դ. սխալ է","scoring_notes":"4 x 0,25 միավոր"},{"number":6,"points":1,"type":"diagram","answer":"ա. Օղակի մեջ է վերցրել բույսերին (առնվազն 2 ավտոտրոֆ); բ. Կատարում են ֆոտոսինթեզ և արտադրում թթվածին","scoring_notes":"ա. 2 x 0,25; բ. 0,5 միավոր. Նկարից կախված"},{"number":7,"points":1,"type":"short_answer","answer":"2, 4, 1, 3, 5, 6"},{"number":8,"points":0.5,"type":"short_answer","answer":"Ֆոտոսինթեզի ժամանակ բույսը կլանում է ածխաթթու գազ և այն վերափոխում ածխածնի այլ միացության","accepted_variants":["նվազեցնում է մթնոլորտում ածխաթթու գազի քանակը","կուտակում է ածխածին գլյուկոզի տեսքով"],"scoring_notes":"Նկարից կախված"},{"number":9,"points":0.5,"type":"short_answer","answer":"ա. Սունկը ծառից ստանում է թթվածին և օրգանական նյութեր; բ. Ծառը սնկից ստանում է հանքային աղեր և ջուր","scoring_notes":"2 x 0,25 միավոր. Նկարից կախված"},{"number":10,"points":1,"type":"table","answer":"ա - շարակցական; բ - նյարդային; գ - մկանային; դ - էպիթելային","scoring_notes":"4 x 0,25 միավոր. Նկարից կախված"},{"number":11,"points":1,"type":"short_answer","answer":"ա. Այո՛, հնարավոր է, որովհետև նոր պտուղները ստացվում են երկու ծնողներից, որոնք ունեն նշված հատկանիշները — կարող են լինել համեղ մի ծնողից և դիմացկուն հիվանդությունների նկատմամբ մյուսից; բ. Սա սեռական բազմացման օրինակ է, քանի որ դրա ժամանակ ի հայտ են գալիս գենետիկորեն նոր օրգանիզմներ, որոնք նման են և՛ մայրական, և՛ հայրական ձևին","scoring_notes":"4 x 0,25 միավոր"},{"number":12,"points":1,"type":"essay","answer":"Գործոն 1՝ Ջրի աղտոտումը — արդյունաբերական կամ կենցաղային թափոնների մուտքը լիճ նվազեցնում է ջրում լուծված թթվածնի քանակը, ինչի հետևանքով ձկները սատկում են, իսկ բույսերը՝ չորանում. Գործոն 2՝ Ջրի մակարդակի իջեցում — երաշտի կամ ջրի արհեստական հեռացման պատճառով ազդում է թե՛ բույսերի, թե՛ կենդանիների կենսապայմանների վրա. Այս գործոնները խաթարում են լճի բնական հավասարակշռությունը","scoring_notes":"2 x 0,5 միավոր"},{"number":13,"points":1.5,"type":"essay","answer":"ա. Տերևը կանաչից կդառնա դեղնավուն կամ գունատ, քանի որ քլորոֆիլ չի լինի; բ. Բույսը չի կարողանա ֆոտոսինթեզ անել և սնունդ պատրաստել — աճը կդանդաղի, բույսը կմահանա; գ. Բույսերով սնվող միջատները, կենդանիները և մարդիկ սնունդ չեն ունենա, ամբողջ սննդային շղթան կխախտվի, բացի այդ թթվածին չի արտադրվի","scoring_notes":"3 x 0,5 միավոր"},{"number":14,"points":1.5,"type":"computation","answer":"1 օր = 86400 վրկ; 0,8 վրկ-ում փորոքները կծկվում են 0,3 վրկ, ուստի x = 86400 x 0,3 : 0,8 = 32400 վրկ; 32400 : 3600 = 9 ժամ","scoring_notes":"Խնդիրը կարող է լուծվել նաև 0,8 վայրկյանը ժամ դարձնելով"},{"number":15,"points":2,"type":"essay","answer":"ա. Սեռական բազմացման ժամանակ ծնողների հատկանիշները փոխանցվում են երեխաներին — ժառանգական նյութի փոխանցմամբ որոշվում են բնութագրեր (հիշողություն, ուշադրություն), որոնք ազդում են սովորելու կարողության վրա; բ. Այո, երեխան կարող է զարգացնել իր կարողությունները միջավայրի շնորհիվ՝ ուսուցչի աջակցությամբ կամ փորձով, նույնիսկ եթե գեները սահմանափակում են նախնական մակարդակը; գ. Սովորելու կարողությունը կախված է գեներից և միջավայրից միասին — նման գեներով երկու երեխա կարող են տարբեր կերպ սովորել, եթե ընտանիքներն ու դպրոցները տարբեր են","scoring_notes":"ա. 0,5; բ. 0,5; գ. 1 միավոր. Չափանիշներ՝ ա. նշել է ծնողներից կախվածությունը սեռական բազմացման համատեքստում; բ. նշել է միջավայրի դերը; գ. արտահայտել է տեսակետը՝ հիմնավորելով"}]'::jsonb, '2025-2026 edition. Q1, Q3, Q4, Q6, Q8, Q9, Q10 are figure-dependent. Q14''s source solution writes ''0,4'' mid-line where it should be 0,3 — the stated result (32400 վրկ = 9 ժամ) is correct for 0,3, so the typo is in the working, not the answer.', '1bLFzdNOVrLYmeekrinLxp-X4Sy5_CrzIiMBA6HW0yVU')
