INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('chemistry', 7, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"multiple_choice","answer":"բ. ալյումինե գդալ"},{"number":2,"points":0.5,"type":"fill_blank","answer":"Պարզ նյութ"},{"number":3,"points":1,"type":"short_answer","answer":"ա. ատոմ; բ. միջուկ","scoring_notes":"2 x 0,5 միավոր"},{"number":4,"points":1,"type":"short_answer","answer":"ա. Եռում, գոլորշիացում; բ. Բնության մեջ, խոհանոցում (օր. լվացքի չորանալը, թեյ եփելը)","scoring_notes":"2 x 0,5 միավոր"},{"number":5,"points":1,"type":"table","answer":"Կերակրի աղ +; Ֆոսֆոր +; Կաթ -; Օդ -","scoring_notes":"4 x 0,25 միավոր"},{"number":6,"points":1,"type":"true_false","answer":"Սխալ է; Ճիշտ է; Ճիշտ է; Սխալ է","scoring_notes":"4 x 0,25 միավոր"},{"number":7,"points":1,"type":"short_answer","answer":"Ցանկացած 2 անվտանգության կանոն, օր.՝ սպիրտայրոցը փչելով չհանգցնել, առանց ուսուցչի լաբորատորիա չմտնել, առանց պիտակի նյութեր չօգտագործել, նյութերից հոտ չքաշել, չհամտեսել","scoring_notes":"2 x 0,5 միավոր"},{"number":8,"points":0.5,"type":"fill_blank","answer":"HNO3"},{"number":9,"points":0.5,"type":"short_answer","answer":"Անոթով փակելիս սահմանափակվում է թթվածնի մուտքը, իսկ այրումն առանց թթվածնի հնարավոր չէ"},{"number":10,"points":1,"type":"table","answer":"Պարզ ատոմային՝ P, K; Պարզ մոլեկուլային՝ H2, O3; Բարդ՝ CO, HNO3","scoring_notes":"4 x 0,25 միավոր"},{"number":11,"points":1,"type":"short_answer","answer":"Նմանություն՝ երկուսն էլ ջրում չեն լուծվում, երկուսն էլ չեն այրվում. Տարբերություն՝ երկաթը պինդ է, ձեթը՝ հեղուկ; երկաթը ժանգոտում է, ձեթը՝ ոչ; երկաթը պարզ նյութ է, ձեթը՝ ոչ","scoring_notes":"4 x 0,25 միավոր՝ 2 տարբերություն և 2 նմանություն"},{"number":12,"points":1,"type":"short_answer","answer":"ա. 4-րդ փորձանոթը; բ. Հեղուկից գազային; գ. Ոչ, եռալուց հետո ջերմաստիճանն այլևս չի բարձրանում; դ. Հաղորդված ջերմությունը ծախսվում է միայն գազագոյացման վրա","scoring_notes":"4 x 0,25 միավոր"},{"number":13,"points":1.5,"type":"short_answer","answer":"ա. Ի հայտ են գալիս պղպջակներ; բ. Սոդայի և քացախի ռեակցիայից անջատվում է ածխաթթու գազ; գ. Անջատված գազը թափանցում է խմորի մեջ և դարձնում ծակոտկեն","scoring_notes":"3 x 0,5 միավոր"},{"number":14,"points":1.5,"type":"short_answer","answer":"ա. Սնդիկը սենյակային ջերմաստիճանում հեղուկ է, ցածր հալման ջերմաստիճան ունի, թափանցիկ չէ, տաքանալիս հատկությունները չի փոխում; բ. Ջերմաստիճանը բարձրանալիս սնդիկն ընդարձակվում է և սյունը բարձրանում է; գ. Ոչ, վոլֆրամը դժվարահալ մետաղ է","scoring_notes":"3 x 0,5 միավոր"},{"number":15,"points":2,"type":"essay","answer":"Մոդելային պատասխան՝ աշակերտն անվանում է նյութը, նշում ագրեգատային վիճակը, ֆիզիկական հատկությունները (գույն, հոտ, համ, լուծելիություն), քիմիական հատկությունները, անվտանգության կանոնները, նմանօրինակ գոյություն ունեցող նյութը, կիրառությունը և ընտրության հիմնավորումը","scoring_notes":"Յուրաքանչյուր լրացված պահանջին 0,25 միավոր"}]'::jsonb, 'Source Հավելված 1 Q6 lists different statements than the Q6 table in the test body — flagged for content review.', '1ZLp243ot5kw7qhnmPcirvg776ghhEjve')
