INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('phys_ed', 11, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"multiple_choice","answer":"Տարբեր ազգերի միջև բարիդրացիական հարաբերությունների ստեղծումը և ամրապնդումը"},{"number":2,"points":0.5,"type":"multiple_choice","answer":"Վազք, բարձրացատկ","scoring_notes":"2 x 0,25 միավոր"},{"number":3,"points":1,"type":"short_answer","answer":"Կծկում, գլորումներ, գլուխկոնծի (առաջ, հետ), կանգ թիակների վրա, կանգ գլխի և ձեռքերի վրա, կամուրջ","accepted_variants":["կծկում","գլորումներ","գլուխկոնծի","կանգ թիակների վրա","կանգ գլխի և ձեռքերի վրա","կամուրջ"],"scoring_notes":"4 x 0,25 միավոր՝ ցանկացած չորս վավեր վարժություն"},{"number":4,"points":1,"type":"table","answer":"Երկու թիմով; յուրաքանչյուր թիմում առնվազն 12 խաղացող; խաղադաշտում խաղում են 5-ը; խաղն ավարտվում է սահմանված ժամանակի ավարտին","scoring_notes":"4 x 0,25 միավոր"},{"number":5,"points":1,"type":"short_answer","answer":"Վերջույթի համար ստեղծել հանգիստ վիճակ; ձգված տեղում դնել պինդ վիրակապ և սառը թրջոց (կամ սառեցնող այլ միջոց)","scoring_notes":"2 x 0,5 միավոր"},{"number":6,"points":1,"type":"table","answer":"Ֆիզիկական՝ մկանային հզորության և դիմացկունության բարձրացում, ճկունության և շարժունակության բարելավում, սրտանոթային առողջության ամրապնդում, քաշի վերահսկում. Հոգեբանական՝ սթրեսի նվազեցում և տրամադրության բարելավում, քնի որակի բարելավում, հոգեկան առողջության ամրապնդում, ինքնագնահատականի և ինքնավստահության բարձրացում","scoring_notes":"2 x 0,5 միավոր"},{"number":7,"points":1,"type":"short_answer","answer":"1904 թ. ստեղծվեց Ֆուտբոլի միջազգային ֆեդերացիան (ՖԻՖԱ), որը ստանձնեց համաշխարհային ֆուտբոլը ղեկավարելու և զարգացնելու պարտավորությունը՝ կազմակերպելով աշխարհի առաջնություններ և միջազգային մրցաշարեր","scoring_notes":"2 x 0,5 միավոր՝ տարեթիվ + դեր"},{"number":8,"points":0.5,"type":"short_answer","answer":"Սեղմել վնասվածքի վայրը; տեղադրել սեղմիչ (ձեռքի կամ ոտքի վրա) վերքից վեր — սա կանխում է արյան հետագա կորուստը և նվազեցնում լուրջ բարդությունների ռիսկը","scoring_notes":"2 x 0,25 միավոր՝ երկու տարբերակ. Նկարից կախված"},{"number":9,"points":0.5,"type":"short_answer","answer":"Վնասվածքի անշարժացում հատուկ հենակներով; ցավազրկում; սառը կոմպրես այտուցն ու ցավը մեղմելու համար; վնասված հատվածի ֆունկցիոնալության ստուգում; տուժածի տեղափոխման զգույշ կազմակերպում","accepted_variants":["անշարժացում","ցավազրկում","սառը կոմպրես","ֆունկցիոնալության ստուգում","զգույշ տեղափոխում"],"scoring_notes":"2 x 0,25 միավոր՝ ցանկացած երկու վավեր նմանություն"},{"number":10,"points":1,"type":"computation","answer":"Նռնակի նետում (մ) — տղաներ՝ 34 և բարձր = 1; 32-30 = 0.75; 28-26 = 0.5; 24-22 = 0.25; 21 և ցածր = 0. Աղջիկներ՝ 22 և բարձր = 1; 20-18 = 0.75; 16-14 = 0.5; 13-12 = 0.25; 11 և ցածր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":11,"points":1,"type":"computation","answer":"Ձգումներ (տղաներ)՝ 9-13 և բարձր = 0.5; 8-4 և ցածր = 0.25. Մարզանստարանից հրումներ (աղջիկներ)՝ 14-19 և բարձր = 0.5; 13-7 և ցածր = 0.25","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ. ՈՒՇԱԴՐՈՒԹՅՈՒՆ՝ աղբյուրի աղյուսակը թերի է — հարցը 1 միավոր է, բայց նշված են միայն 0,5 և 0,25 շեմերը"},{"number":12,"points":1,"type":"computation","answer":"Հեռացատկ տեղից (սմ) — տղաներ՝ 235 և բարձր = 1; 230-220 = 0.75; 215-210 = 0.5; 205-200 = 0.25; 199 և ցածր = 0. Աղջիկներ՝ 185 և բարձր = 1; 180-175 = 0.75; 170-165 = 0.5; 160-155 = 0.25; 154 և ցածր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":13,"points":1.5,"type":"computation","answer":"ա. Վազք 30 մ — տղաներ՝ 4.6 և ցածր = 0.75; 5.0 = 0.5; 5.2-5.8 = 0.25; 5.9 և բարձր = 0. Աղջիկներ՝ 5.3 և ցածր = 0.75; 5.6 = 0.5; 5.8-6.5 = 0.25; 6.6 և բարձր = 0. բ. Վազք 100 մ — տղաներ՝ 14.6 և ցածր = 0.75; 14.5 = 0.5; 14.8-15.5 = 0.25; 15.6 և բարձր = 0. Աղջիկներ՝ 16.8 և ցածր = 0.75; 16.5 = 0.5; 17.0-17.8 = 0.25; 18.0 և բարձր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ՝ երկու ենթամաս, յուրաքանչյուրը մինչև 0,75 միավոր. Սկանից գնահատելի չէ"},{"number":14,"points":1.5,"type":"essay","answer":"Հանդբոլում յուրաքանչյուր թիմում խաղում է 7 խաղացող; եթե խաղացողների թիվը գերազանցում է 7-ը, դա կհանգեցնի տուգանքների կամ դաշտից խաղացողի հեռացման; եթե թիվը պակաս է, թիմը կարող է շարունակել խաղը, սակայն դա մեծացնում է մրցակցի հաղթելու հնարավորությունները","scoring_notes":"3 x 0,5 միավոր՝ երկուսից երեք նախադասությամբ"},{"number":15,"points":2,"type":"essay","answer":"Մոդելային պատասխան՝ աշակերտը տալիս է նոր մարզախաղի անվանում, թվարկում է համակցված տարրերը գոյություն ունեցող մարզաձևերից (օր.՝ ֆուտբոլից՝ հարվածներ և գնդակի վերահսկում, վոլեյբոլից՝ ցանցային խաղ և փոխանցում, հանդբոլից՝ գոլ խփելը, բասկետբոլից՝ գնդակի վարում և օղակ), ձևակերպում է նպատակը, կանոնները (թիմերի կազմ, խաղադաշտ, միավորների վաստակում) և գնահատման կարգը","scoring_notes":"Գնահատվում է անվանման, համակցված տարրերի, նպատակների, կանոնների և գնահատման ամբողջականությունը"}]'::jsonb, '2024-2025 edition. Q10-Q13 are PHYSICAL performance tasks filled in by the teacher from measured results — not scoreable from a scan. TWO SOURCE DEFECTS: (1) Հավելված 1 contains a spurious duplicate at position 7 (it repeats the Q3 acrobatics answer), which shifts the printed answers for Q7-Q9 one place down; realigned here against the question text. (2) The Q11 conversion table only lists the 0.5 and 0.25 bands although the question is worth 1 point — the top band is missing and needs the content team. Q8 is figure-dependent.', '1SyivDKRh5uenAbpPlCr8nur_NQ28lirxoJOzzJOvbFE')
ON CONFLICT (subject_id, grade, test_type, year) DO UPDATE
  SET answer_key = EXCLUDED.answer_key, scoring_notes = EXCLUDED.scoring_notes, source_file_id = EXCLUDED.source_file_id, total_points = EXCLUDED.total_points;

INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('phys_ed', 12, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"multiple_choice","answer":"«Արագ», «Բարձր», «Ուժեղ»"},{"number":2,"points":0.5,"type":"diagram","answer":"Զուգափայտ, նժույգ","scoring_notes":"2 x 0,25 միավոր. Նկարից կախված"},{"number":3,"points":1,"type":"diagram","answer":"Թափավազքով հեռացատկի փուլերը՝ թափավազք, հրում, թռիչք, վայրէջք","scoring_notes":"4 x 0,25 միավոր. ԱՂԲՅՈՒՐԻ ԲԱՆԱԼԻՆ ԴԱՏԱՐԿ Է — վերը բերվածը ստանդարտ փուլերն են, ճշտել բովանդակային խմբի հետ. Նկարից կախված"},{"number":4,"points":1,"type":"table","answer":"Օրինակ՝ Կանոն՝ գնդակի խաղադաշտի կողային սահմաններից դուրս գալը — Հետևանք՝ գնդակը տրվում է հակառակորդ թիմին, որը ձեռքով փոխանցում կատարելով խաղընկերոջը գնդակը մտցնում է խաղի մեջ. Ընդունվում է ցանկացած չորս վավեր կանոն՝ համապատասխան հետևանքով","scoring_notes":"4 x 0,25 միավոր"},{"number":5,"points":1,"type":"short_answer","answer":"Ախտանշաններ՝ ծարավի և հոգնածության զգացում, գլխացավ, թուլություն, մաշկը կարմրում է, ապա գունատվում, ջերմությունը բարձրանում է, շնչառությունը և սրտի աշխատանքն արագացած են, հնարավոր է սրտխառնոց և գիտակցության կորուստ. Առաջին օգնություն՝ տուժածին տեղափոխել ստվերոտ, սառը տեղ, խմեցնել սառը ըմպելիքներ, մարմնին դնել սառը թրջոցներ կամ փաթաթել թաց սավանով","scoring_notes":"2 x 0,25 միավոր՝ ախտանշաններ + 0,5 միավոր՝ առաջին օգնություն"},{"number":6,"points":1,"type":"table","answer":"Տղաներ և պատանիներ՝ մինչև 15-16 տ. 2.40 մ, մինչև 17-18 տ. 2.43 մ; Աղջիկներ՝ մինչև 15-16 տ. 2.20 մ, մինչև 17-18 տ. 2.24 մ","scoring_notes":"4 x 0,25 միավոր"},{"number":7,"points":1,"type":"short_answer","answer":"Հիմնականում ցրտահարվում են մարմնի բաց մասերը՝ քիթը, ականջը, մատները, մաշկը, առավել հաճախ վերջույթները; խուսափելու համար պետք է վերջույթները ծածկել, լինել ակտիվ շարժման մեջ և խուսափել ստատիկ դիրքում մնալուց","scoring_notes":"2 x 0,5 միավոր՝ երկուսից երեք նախադասությամբ"},{"number":8,"points":0.5,"type":"table","answer":"Նմանություն՝ երկու խաղում էլ խաղը բաժանվում է երկու կեսի, որոնց միջև առկա է հանգստի ժամանակ. Տարբերություն՝ ֆուտբոլում խաղում է 11 խաղացող, մինի ֆուտբոլում՝ 5","scoring_notes":"2 x 0,25 միավոր"},{"number":9,"points":0.5,"type":"essay","answer":"Դերերի հստակեցում՝ խաղից առաջ բոլոր թիմակիցները պետք է հասկանան իրենց պարտականություններն ու դերերը, ինչը նվազեցնում է կոնֆլիկտները; բաց և վստահելի հաղորդակցություն թիմի ներսում՝ հստակ, ներառական և հիմնված բոլոր անդամների գաղափարների վրա","scoring_notes":"2 x 0,25 միավոր՝ նվազագույնը 2 նախադասություն"},{"number":10,"points":1,"type":"computation","answer":"Նռնակի նետում (մ) — տղաներ՝ 38 և բարձր = 1; 36-34 = 0.75; 32-30 = 0.5; 29-26 = 0.25; 25 և ցածր = 0. Աղջիկներ՝ 23 և բարձր = 1; 22-20 = 0.75; 19-17 = 0.5; 16-14 = 0.25; 13 և ցածր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":11,"points":1,"type":"computation","answer":"Ձգումներ (տղաներ)՝ 10 և ավել = 1; 9-7 = 0.75; 6-5 = 0.5; 4-3 = 0.25; 2 և ցածր = 0. Մարզանստարանին հրումներ (աղջիկներ)՝ 16 և ավել = 1; 15-13 = 0.75; 12-10 = 0.5; 8-4 = 0.25; 3 և ցածր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":12,"points":1,"type":"computation","answer":"Հեռացատկ տեղից (սմ) — տղաներ՝ 240 և բարձր = 1; 239-230 = 0.75; 229-220 = 0.5; 219-210 = 0.25; 209 և ցածր = 0. Աղջիկներ՝ 190 և բարձր = 1; 189-180 = 0.75; 179-170 = 0.5; 169-160 = 0.25; 159 և ցածր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":13,"points":1.5,"type":"computation","answer":"ա. Վազք 30 մ — տղաներ՝ 4.4-4.5 և ցածր = 0.75; 4.6-4.9 = 0.5; 5.0-5.6 = 0.25; 5.7 և բարձր = 0. Աղջիկներ՝ 5.1-5.2 և ցածր = 0.75; 5.3-5.6 = 0.5; 5.7-6.3 = 0.25; 6.4 և բարձր = 0. բ. Վազք 1000 մ (տղաներ)՝ 3.40-3.41 և ցածր = 0.75; 3.45-3.51 = 0.5; 3.55-4.10 = 0.25; 4.11 և բարձր = 0. Վազք 500 մ (աղջիկներ)՝ 1.50-1.51 և ցածր = 0.75; 1.55-2.01 = 0.5; 2.05-2.20 = 0.25; 2.21 և բարձր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ՝ 2 x 0,75 միավոր. Սկանից գնահատելի չէ"},{"number":14,"points":1.5,"type":"essay","answer":"Վնասված վերջույթի անշարժացում՝ առաջին հերթին անհրաժեշտ է անշարժացնել վնասված վերջույթը, որպեսզի կանխվի հոդերի և ոսկրերի հետագա վնասումը — կարելի է օգտագործել կոշտ առարկաներ, կապելով վնասված տարածքի երկայնքով. Կողմնային հենակների տեղադրում՝ վերջույթը ֆիքսել հենակներով՝ ապահովելու կայունությունը, հենակները պետք է լինեն և՛ վնասված մասի ներքևում, և՛ վերևում","scoring_notes":"Քայլերի հերթականություն + հիմնավորում. Նկարից կախված"},{"number":15,"points":2,"type":"essay","answer":"Ակրոբատիկական վարժությունները զարգացնում են ժամանակի և տարածության մեջ կողմնորոշվելու կարողությունը, ճկունությունը, արագաշարժությունը և շարժումների կոորդինացիան; աշակերտը պետք է վերլուծի այս կարողությունների կարևորությունը և ազդեցությունը մարզիկի վրա","scoring_notes":"Նվազագույնը 4 նախադասություն"}]'::jsonb, '2024-2025 edition. Q10-Q13 are PHYSICAL performance tasks filled in by the teacher from measured results — not scoreable from a scan. GAP IN SOURCE KEY: Q3 (name the running-long-jump phases on the picture) has an EMPTY answer in Հավելված 1 and needs the content team; the standard phases are թափավազք / հրում / թռիչք / վայրէջք. Q2, Q3 and Q14 are figure-dependent.', '1syRjGY-GgLuQjoZ7nGcxmXjaGZ6ibodG_95khy9kbYE')
