INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('phys_ed', 5, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"short_answer","answer":"Ֆրանսիա, Շամոնի քաղաք; 1924 թ.","scoring_notes":"2 x 0,25 միավոր՝ երկիր + տարեթիվ"},{"number":2,"points":0.5,"type":"short_answer","answer":"Տարվա տաք եղանակներին, առավոտյան ժամերին","scoring_notes":"2 x 0,25 միավոր"},{"number":3,"points":1,"type":"diagram","answer":"Առողջ ապրելակերպի բաղադրիչները՝ լրացվում են նկարի բաց հատվածներում","scoring_notes":"4 x 0,25 միավոր. Նկարից կախված"},{"number":4,"points":1,"type":"short_answer","answer":"Ցանկացած չորս շարժախաղ, օր.՝ էստաֆետ նշանառությամբ, Թունել, Համարականչ, էստաֆետ գնդակի վարումով, Հրոցի, Պարկերով ցատկ","accepted_variants":["էստաֆետ նշանառությամբ","Թունել","Համարականչ","էստաֆետ գնդակի վարումով","Հրոցի","Պարկերով ցատկ"],"scoring_notes":"4 x 0,25 միավոր՝ ցանկացած չորս վավեր շարժախաղ"},{"number":5,"points":1,"type":"short_answer","answer":"Ձեռքի ափը դնել պարանոցի, քունքի կամ ձեռքի վրա; անոթազարկը հաշվել 10 վրկ-ի ընթացքում, ապա բազմապատկել 6-ով"},{"number":6,"points":1,"type":"short_answer","answer":"Գլուխը և իրանը թեքված են մի փոքր առաջ, ձեռքերը կիսածալված են արմնկային հոդում և բնական շարժվում են առաջ մինչև կրծքի մակարդակը և հետ"},{"number":7,"points":1,"type":"short_answer","answer":"Մարմնամարզական պատ, այծիկ, մարմնամարզական գերան, պտտաձող","scoring_notes":"4 x 0,25 միավոր"},{"number":8,"points":0.5,"type":"short_answer","answer":"Ազատ և լավ դիրքում գտնվող թիմակցի ընտրություն; որոշակի դիրք ընդունել, որը թույլ կտա հեշտությամբ տեղափոխվել և հավասարակշռություն պահպանել; փոխանցման ճիշտ տեխնիկա կիրառել; հետևել գնդակի ուղղությանը","scoring_notes":"2 x 0,25 միավոր՝ երկու քայլ"},{"number":9,"points":0.5,"type":"short_answer","answer":"Ցատկեր ձեռքերը վեր նետելով — զարգացնում է ձեռքերի և ոտքերի համաժամանակյա աշխատանքը, ձեռքերի ուժեղ շարժումը վեր ավելացնում է ցատկի բարձրությունը և զարգացնում պայթյունային ուժը","scoring_notes":"Ցանկացած ցանկից ընտրված վարժություն՝ ճիշտ հիմնավորմամբ"},{"number":10,"points":1,"type":"computation","answer":"Վազք 30 մ, գնահատման կարգ — աղջիկներ՝ 6.4 և ցածր = 1; 6.6-6.8 = 0.75; 7.0-7.4 = 0.5; 7.8-8.0 = 0.25; 8.1 և բարձր = 0. Տղաներ՝ 6.0 և ցածր = 1; 6.2-6.6 = 0.75; 6.8-7.0 = 0.5; 7.1-7.2 = 0.25; 7.3 և բարձր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — աշակերտը թողնում է դատարկ, ուսուցիչը լրացնում է ըստ հանձնած նորմատիվի. Սկանից գնահատելի չէ"},{"number":11,"points":1,"type":"computation","answer":"Ձգումներ (տղաներ)՝ 7 և բարձր = 1; 6-5 = 0.75; 4-3 = 0.5; 2-1 = 0.25. Մարզանստարանին հրումներ (աղջիկներ)՝ 8 և բարձր = 1; 7-6 = 0.75; 5-4 = 0.5; 3-2 = 0.25","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":12,"points":1,"type":"computation","answer":"Հեռացատկ տեղից (սմ) — տղաներ՝ 165 և բարձր = 1; 155-150 = 0.75; 140-130 = 0.5; 120-115 = 0.25; 114 և ցածր = 0. Աղջիկներ՝ 145 և բարձր = 1; 135-130 = 0.75; 125-120 = 0.5; 115-110 = 0.25; 109 և ցածր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":13,"points":1.5,"type":"matching","answer":"Կախը՝ մարմնի դիրքն է գործիքի վրա, երբ ուսերի դիրքը ցածր է բռնվածքից — զարգացնում է ուժ, դիմացկունություն, ճկունություն. Հենումը՝ երբ ուսերի դիրքը բարձր է բռնվածքից — զարգացնում է կոորդինացիա, ուժ","scoring_notes":"2 x 0,75 միավոր"},{"number":14,"points":1.5,"type":"short_answer","answer":"Քայլ 1՝ գնդակի դիրքի ստուգում; Քայլ 2՝ դարպասապահի դիրքի ուսումնասիրում; Քայլ 3՝ հարվածի ուժի և ճշգրտության ընտրություն","scoring_notes":"3 x 0,5 միավոր"},{"number":15,"points":2,"type":"essay","answer":"Առողջ սննդակարգը մեծ ազդեցություն ունի առօրյա գործունեության վրա — բազմազան սնունդը (վիտամիններ, սպիտակուցներ, ածխաջրեր) տալիս է ավելի շատ էներգիա և ուշ հոգնածություն. Ոչ, բոլորը չպետք է հետևեն նույն սննդակարգին — երեխաները, մեծահասակները և մարզիկները տարբեր քանակով սննդանյութեր են պահանջում, իսկ ալերգիա կամ առողջական խնդիր ունեցողները՝ հատուկ սննդակարգ","scoring_notes":"1 + 1 միավոր՝ ազդեցությունը + հիմնավորված դիրքորոշում"}]'::jsonb, '2024-2025 edition. IMPORTANT: Q10, Q11 and Q12 are PHYSICAL performance tasks (30m sprint, pull-ups/push-ups, standing long jump). The test paper explicitly instructs students to leave them blank — the teacher fills them in from measured results. An AI scoring a scan cannot judge these; the key carries the official conversion tables so a recorded measurement can be converted, but the scan alone will show blanks. Q3 is figure-dependent (health-lifestyle diagram).', '1evMV5gyM2AFAlcC5I0NbItNAUHu2DfUQprI4eUy1-C8')
ON CONFLICT (subject_id, grade, test_type, year) DO UPDATE
  SET answer_key = EXCLUDED.answer_key, scoring_notes = EXCLUDED.scoring_notes, source_file_id = EXCLUDED.source_file_id, total_points = EXCLUDED.total_points;

INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('phys_ed', 7, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"short_answer","answer":"Խաղակես՝ 2; խաղի մասնակիցների քանակ՝ 11","scoring_notes":"2 x 0,25 միավոր"},{"number":2,"points":0.5,"type":"diagram","answer":"Երկու աթլետիկական վարժություն՝ նշված պատկերներից","scoring_notes":"Մեկ ճիշտ պատասխան՝ 0,25; երկուսը՝ 0,5 միավոր. Նկարից կախված"},{"number":3,"points":1,"type":"matching","answer":"Ա (40x20 մ) - 3 Հանդբոլ; Բ (105x70 մ) - 4 Ֆուտբոլ; Գ (28x15 մ) - 2 Բասկետբոլ; Դ (18x9 մ) - 1 Վոլեյբոլ","scoring_notes":"4 x 0,25 միավոր. ՈՒՇԱԴՐՈՒԹՅՈՒՆ՝ աղբյուրի բանալին Ա-1 և Դ-3 է տալիս, ինչը վոլեյբոլն ու հանդբոլը տեղափոխում է իրար տեղ — ճշտել բովանդակային խմբի հետ"},{"number":4,"points":1,"type":"short_answer","answer":"Ժամանակակից օլիմպիական խաղերը սկսել են անցկացվել 1896 թվականին; 1896-1952 թթ. հայ մարզիկները չեն մասնակցել, քանի որ գտնվում էին ԽՍՀՄ կազմում, որը ՄՕԿ-ի անդամ չէր","scoring_notes":"2 x 0,5 միավոր"},{"number":5,"points":1,"type":"short_answer","answer":"Մարաթոնյան վազք; 42 կմ 195 մ","scoring_notes":"2 x 0,5 միավոր"},{"number":6,"points":1,"type":"fill_blank","answer":"ուսուցչի (ներկայությամբ); մարզագույք և առարկաներ (տեղափոխելիս); վարժատեղին շատ մոտ","scoring_notes":"4 x 0,25 միավոր"},{"number":7,"points":1,"type":"short_answer","answer":"Անհատական պաշտպանությունը հանդբոլում ուղղված է հակառակորդի խաղացողներին վերահսկելուն և նրանց առաջխաղացումը կանխելուն; օգնում է պաշտպանվող թիմին խախտել հարձակվող թիմի խաղային ռիթմը՝ սահմանափակելով հակառակորդի մանևրելու հնարավորությունները","scoring_notes":"2 x 0,5 միավոր"},{"number":8,"points":0.5,"type":"short_answer","answer":"Ելման դրություն՝ կախված մեկ ձեռքով; «1» հաշվին ոտքերը ծալել վեր և պարանը բռնել թաթերով; «2» հաշվին ոտքերով սեղմել, կանգնել և մարմինը տեղափոխել վեր, ծալած ձեռքերը տարածել վեր և վերաբռնել պարանը"},{"number":9,"points":0.5,"type":"diagram","answer":"Վոլեյբոլի մարզադաշտի մոդելավորում՝ լայնություն և երկարություն (0,25) + խաղացողների դիրքերը (0,25)","scoring_notes":"2 x 0,25 միավոր. Գծագրից կախված"},{"number":10,"points":1,"type":"computation","answer":"Վազք 30 մ — աղջիկներ՝ 5.8 և ցածր = 1; 6.0-6.2 = 0.75; 6.5-7.0 = 0.5; 7.4-7.6 = 0.25; 7.7 և բարձր = 0. Տղաներ՝ 5.5 և ցածր = 1; 5.6-5.8 = 0.75; 6.0-6.4 = 0.5; 6.6-6.8 = 0.25; 6.9 և բարձր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է ըստ նորմատիվի. Սկանից գնահատելի չէ"},{"number":11,"points":1,"type":"computation","answer":"Ձգումներ (տղաներ)՝ 8 = 1; 7-6 = 0.75; 5-4 = 0.5; 3-1 = 0.25. Մարզանստարանին հրումներ (աղջիկներ)՝ 12 = 1; 11-9 = 0.75; 8-6 = 0.5; 5-4 = 0.25","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":12,"points":1,"type":"essay","answer":"Առավոտյան վարժանքներ՝ օրը սկսել մարմնամարզական վարժություններով (ցատկեր, կքանստումներ, թռիչքներ), ինչը կօգնի զարթնել, ակտիվացնել արյան շրջանառությունը և պատրաստել մարմինը օրվա ակտիվության համար; տանը կամ բացօթյա կիրառել պարզ վարժություններ՝ կողմնակի պտույտներ, խորը կքանստումներ, հետադարձ ոտքի ձգումներ","scoring_notes":"2 x 0,5 միավոր՝ առնվազն 2 նախադասություն"},{"number":13,"points":1.5,"type":"essay","answer":"Առավոտյան՝ հիգիենիկ մարմնամարզություն 10-12 րոպե ամեն օր. Կեսօրին՝ ֆիզիկական կուլտուրայի դասեր շաբաթը 3 անգամ 45 րոպե, շարժախաղեր և ֆիզիկական վարժություններ 45 րոպե. Երեկոյան՝ խաղեր և զբոսանքներ 30 րոպե, տնային հանձնարարությունների կատարում 15-20 րոպե, մարզական խմբակ շաբաթական 6 ժամ","scoring_notes":"3 x 0,5 միավոր՝ առավոտ / կեսօր / երեկո"},{"number":14,"points":1.5,"type":"table","answer":"Ֆիզիկական հատկանիշ — կարճ տարածություն՝ շատ բարձր արագություն և պայթուցիկ ուժ; երկար տարածություն՝ բարձր դիմացկունություն երկարատև ծանրաբեռնվածությանը դիմանալու համար. Տեխնիկական հատկանիշ — կարճ տարածություն՝ արագ մեկնարկ հատուկ մեկնարկային բլոկներից; երկար տարածություն՝ տեմպի կառավարում՝ ուժերը ամբողջ մրցավազքի ընթացքում արդյունավետ բաժանելու համար","scoring_notes":"Ֆիզիկական հատկանիշ՝ 2 x 0,5 = 1 միավոր; տեխնիկական հատկանիշ՝ 2 x 0,25 = 0,5 միավոր"},{"number":15,"points":2,"type":"essay","answer":"Ֆիզիկական կուլտուրան նպաստում է մկանների, ոսկորների, սրտանոթային համակարգի և ընդհանուր շարժունակության զարգացմանը, ինչը կարևոր է առողջության պահպանման և հիվանդությունների կանխարգելման համար; առողջ և ակտիվ կյանք վարելով մարդիկ ավելի երկար են ապրում և ավելի ակտիվ են առօրյայում; հոգեբանական բարեկեցության բարելավումը նպաստում է ավելի երջանիկ կյանքի և առողջ սոցիալական կապերի ձևավորմանը","scoring_notes":"3-4 նախադասության սահմաններում"}]'::jsonb, '2024-2025 edition. Q10 and Q11 are PHYSICAL performance tasks — students leave them blank, the teacher fills them in from measured results; not scoreable from a scan. Q2 and Q9 are figure-dependent. CONTENT ERROR IN SOURCE KEY (Q3): the official key gives Ա-1, Բ-4, Գ-2, Դ-3, which maps volleyball to 40x20 m and handball to 18x9 m. Those two are swapped — a volleyball court is 18x9 and a handball court is 40x20. The factually correct mapping is used here; flag for content review.', '1MMUaREAz2SDFtlb3x1V_ZRmpu8Y6xeaDEHHhN5T8ZfE')
