VALUES ('phys_ed', 8, 'diagnostic', '2025', 15.0, '[{"number":1,"points":0.5,"type":"short_answer","answer":"Տուգանային հարվածի հեռավորությունը՝ 7 մ; իրացման տևողությունը՝ 3 վրկ","scoring_notes":"2 x 0,25 միավոր (աղբյուրի հարցատեքստը սխալմամբ նշում է 1 միավոր)"},{"number":2,"points":0.5,"type":"diagram","answer":"Բարձրացատկի փուլերի անվանումները՝ նշվում են պատկերի վրա","scoring_notes":"ԱՂԲՅՈՒՐԻ ԲԱՆԱԼԻՆ ԴԱՏԱՐԿ Է այս հարցի համար — լրացնել բովանդակային խմբի հետ. Նկարից կախված"},{"number":3,"points":1,"type":"short_answer","answer":"Արագացումով վազքեր, արգելավազքեր, փոխանցումավազքեր, ցատկեր","accepted_variants":["արագացումով վազքեր","արգելավազքեր","փոխանցումավազքեր","ցատկեր"],"scoring_notes":"2 x 0,5 միավոր՝ ցանկացած երկու վավեր վարժություն (աղբյուրի հարցատեքստը սխալմամբ նշում է 0,5 միավոր)"},{"number":4,"points":1,"type":"short_answer","answer":"Նյարդային համակարգի լարվածություն, սրտանոթային հիվանդություններ, նյութափոխանակության խանգարումներ, ճարպակալում","scoring_notes":"4 x 0,25 միավոր"},{"number":5,"points":1,"type":"short_answer","answer":"Սկզբնահարված իրականացվում է ամեն խաղի սկզբում, սեթերի սկզբում, կամ ձախողված սեթից հետո","scoring_notes":"2 x 0,5 միավոր՝ երկու իրավիճակ"},{"number":6,"points":1,"type":"short_answer","answer":"Թափավազք, հրում, թռիչք, վայրէջք","scoring_notes":"4 x 0,25 միավոր"},{"number":7,"points":1,"type":"diagram","answer":"Ճկունությունը զարգացնող վարժությունների ընտրություն պատկերներից","scoring_notes":"ԱՂԲՅՈՒՐԻ ԲԱՆԱԼԻՆ ԴԱՏԱՐԿ Է այս հարցի համար — լրացնել բովանդակային խմբի հետ. Նկարից կախված"},{"number":8,"points":0.5,"type":"multiple_choice","answer":"Բռնել, փոխանցել, գնդակը վարել, զամբյուղի մեջ նետել"},{"number":9,"points":0.5,"type":"short_answer","answer":"Թիմը պետք է փոխարինի դարպասապահին — եթե փոխարինումներ ունի, օգտագործում է դրանցից մեկը; եթե բոլորն օգտագործված են, դարպասապահի դերում պետք է խաղա այլ խաղացող՝ ըստ թիմի դասավորության և մարտավարության"},{"number":10,"points":1,"type":"computation","answer":"Վազք 30 մ — տղաներ՝ 5.2 և ցածր = 1; 5.4-5.6 = 0.75; 5.8-6.0 = 0.5; 6.2-6.4 = 0.25; 6.5 և բարձր = 0. Աղջիկներ՝ 5.7 և ցածր = 1; 5.8-6.0 = 0.75; 6.2-6.5 = 0.5; 7.0-7.4 = 0.25; 7.5 և բարձր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":11,"points":1,"type":"computation","answer":"Ձգումներ (տղաներ)՝ 9 = 1; 8-7 = 0.75; 6-5 = 0.5; 4-3 = 0.25. Մարզանստարանին հրումներ (աղջիկներ)՝ 14 = 1; 13-11 = 0.75; 10-7 = 0.5; 6-4 = 0.25","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":12,"points":1,"type":"computation","answer":"Հեռացատկ տեղից (սմ) — տղաներ՝ 200 և բարձր = 1; 190-180 = 0.75; 170-160 = 0.5; 155-150 = 0.25; 149 և ցածր = 0. Աղջիկներ՝ 170 և բարձր = 1; 165-160 = 0.75; 150-140 = 0.5; 135-130 = 0.25; 129 և ցածր = 0","scoring_notes":"ԳՈՐԾՆԱԿԱՆ ԱՌԱՋԱԴՐԱՆՔ — ուսուցիչը լրացնում է. Սկանից գնահատելի չէ"},{"number":13,"points":1.5,"type":"essay","answer":"Նախավարժանքը (տաքացումը) ֆիզիոլոգիական և հոգեբանական նպաստավոր ազդեցություն ունի՝ մկանների և հոդերի նախապատրաստում, նյարդային համակարգի ակտիվացում, հոգեբանական պատրաստում, վնասվածքների կանխարգելում. Համալիրում պետք է լինի առնվազն 3 ընդհանուր զարգացնող վարժություն","scoring_notes":"3 x 0,5 միավոր"},{"number":14,"points":1.5,"type":"essay","answer":"Տեխնիկայի ճիշտ կիրառումը շատ ավելի կարևոր է, քան արագությունը — այն ապահովում է ոչ միայն կատարողականի որակը, այլև վնասվածքների ռիսկի նվազեցումը; արագությունը կարող է զարգանալ հետագայում, երբ ճիշտ տեխնիկան լիովին յուրացված է","scoring_notes":"2 x 0,75 միավոր՝ դիրքորոշում + հիմնավորում"},{"number":15,"points":2,"type":"essay","answer":"Օլիմպիական խաղերի վերածնունդը մեծ ազդեցություն է ունեցել ներկայիս սպորտի զարգացման վրա՝ որպես միջազգային մակարդակի սպորտային միջոցառում միավորել է տարբեր երկրներ և մշակույթներ, նպաստել է սպորտային արժեքների (թիմային աշխատանք, արդարություն, մրցակցության ոգի) տարածմանը, խթանել է նոր սպորտաձևերի ստեղծումը և մարզական գիտության ու տեխնոլոգիայի զարգացումը","scoring_notes":"4 նախադասության սահմաններում"}]'::jsonb, '2024-2025 edition. Q10, Q11 and Q12 are PHYSICAL performance tasks filled in by the teacher from measured results — not scoreable from a scan (the paper''s warning names only Q10-11, but Q12 is a practical standing-long-jump task with its own conversion table). GAPS IN SOURCE KEY: Q2 (name the high-jump phases on the picture) and Q7 (pick the flexibility exercises from the images) have EMPTY answers in Հավելված 1 — both are figure-based and need the content team to fill them in before those two questions can be auto-scored. POINT CONFLICT IN SOURCE: the question text labels Q1 as ''0.5x2=1 միավոր'' and Q3 as ''0.25x2=0.5 միավոր'', but the paper''s own Հավելված 2 table (and the standardised 15-point distribution) assign Q1=0.5 and Q3=1. The standard distribution is used here, since the scorer clamps every question to it.', '1RP9pFQqGxNVCvnSJWGbv3S1_TwpstKP1H2nzH86pv8s')
